    char value = tempObjectType->m_width;
    if (static_cast<unsigned>(outfile->write(&value, 1)) < 1)
        return -1;
    value = tempObjectType->m_height;
    if (static_cast<unsigned>(outfile->write(&value, 1)) < 1)
        return -1;

